 import unittest
from candidate import sort_numbers

class TestSortNumbers(unittest.TestCase):
    def test_sort_numbers_normalcase_expectedbehavior(self):
        self.assertEqual(sort_numbers('three one five'), 'one three five')

    def test_sort_numbers_edgecase_mixed_case(self):
        self.assertEqual(sort_numbers('THREE one Five'), 'one THREE Five')

    def test_sort_numbers_edgecase_empty_string(self):
        self.assertEqual(sort_numbers(''), '')

    def test_sort_numbers_edgecase_single_number(self):
        self.assertEqual(sort_numbers('five'), 'five')

    def test_sort_numbers_edgecase_single_digit_no_space(self):
        self.assertEqual(sort_numbers('threetwoone'), 'one three two')

    def test_sort_numbers_edgecase_multiple_spaces(self):
        self.assertEqual(sort_numbers('three one    five'), 'one three five')

    def test_sort_numbers_edgecase_leading_and_trailing_spaces(self):
        self.assertEqual(sort_numbers('  three one    five '), 'one three five')

    def test_sort_numbers_edgecase_invalid_input(self):
        self.assertRaises(ValueError, sort_numbers, 'invalid_input')

    def test_sort_numbers_edgecase_invalid_number(self):
        self.assertRaises(ValueError, sort_numbers, 'ten')

    def test_sort_numbers_edgecase_negative_numbers(self):
        self.assertRaises(ValueError, sort_numbers, 'negative one negative two')

if __name__ == '__main__':
    unittest.main()
